# _EXPECTED_BLOB holds the values solution/solve.py writes over environment/data and
# over the two extracts in _EXTRACTS; both are zlib+base64 and are sealed together.
_EXPECTED_BLOB = ''

_EXTRACTS = {
    'A': '',
    'B': '',
}


_ENV = {"PATH": "/usr/local/bin:/usr/bin:/bin", "LANG": "C.UTF-8",
        "HOME": "/tmp", "PYTHONHASHSEED": "0"}
_LOBS = ["wc", "cal", "gl", "cp", "spec"]
_ARTIFACTS = [
    "summary.json", "methodology_audit.json", "data_quality.json",
    "lob_wc.json", "lob_cal.json", "lob_gl.json", "lob_cp.json", "lob_spec.json",
    "treaty_working.json",
]
_CYCLES = ["H%02d" % i for i in range(1, 27)]
_CACHE = {}
_SOLVER_UID = 1002
# rewardkit runs checks on threads; every run of the module as the solver user
# goes through this lock so one run never kills another run's processes.
_RUN_LOCK = threading.RLock()
_DQ_KEYS = ["late_recorded", "duplicate_identical", "duplicate_conflicting",
            "cross_source_collapsed", "fold_disambiguated", "gap_shifted",
            "log_continuations", "unknown_reinsurer_rows", "out_of_horizon_rows",
            "block_unit_rows", "paren_negatives", "restatement_gaps"]
_AUDIT_SECTIONS = ["settlement", "attachment", "endorsements", "reserve_state",
                   "chain_ladder", "allocation"]


def _safe(action):
    try:
        return bool(action())
    except Exception:
        return False


def _int_eq(a, b) -> bool:
    if isinstance(a, bool) or isinstance(b, bool):
        return False
    if not isinstance(a, int) or not isinstance(b, int):
        return False
    return a == b


def _str_eq(a, b) -> bool:
    return isinstance(a, str) and isinstance(b, str) and a == b


def _int_str(v) -> str:
    if isinstance(v, bool) or not isinstance(v, int):
        return "NONINT"
    return str(v)


def _diff_str(a, b) -> str:
    if isinstance(a, bool) or not isinstance(a, int):
        return "NONINT"
    if isinstance(b, bool) or not isinstance(b, int):
        return "NONINT"
    return str(a - b)


def _matches(out: Path, corpus: str, view_keys) -> bool:
    try:
        wanted = _expected().get(corpus, {}).get("digests", {})
    except Exception:
        return False
    if not wanted:
        return False
    found = _digests(out)
    for key in view_keys:
        if key not in wanted or key not in found:
            return False
        if found[key] != wanted[key]:
            return False
    return True


def _expected():
    if "expected" not in _CACHE:
        _CACHE["expected"] = json.loads(zlib.decompress(base64.b64decode(_EXPECTED_BLOB)))
    return _CACHE["expected"]


def _digest(lines):
    return hashlib.sha256("\n".join(lines).encode()).hexdigest()


def _views(out: Path):
    # Reads each LOB document in its shipped order and hashes views over the
    # ledger. The ledger is NOT re-sorted here: a module that emits rows in a
    # different order than the one output_contract.md declares still produces
    # a digest, but it differs from the shipped digest because each view
    # carries the row order.
    backbone, spine, outcome, cells = [], [], [], []
    for lob in _LOBS:
        d = json.loads((out / f"lob_{lob}.json").read_text())
        ledger = d.get("ledger", [])
        for row in ledger:
            stem = "%s|%s|%s" % (lob, row.get("cycle",""), row.get("claim_ref",""))
            backbone.append("%s|%s|%s|%s|%s" % (
                stem, row.get("reinsurer_canonical","") or "",
                row.get("layer",""), _int_str(row.get("ultimate", 0)),
                _int_str(row.get("paid_to_date", 0))))
            spine.append("%s|%s|%s|%s" % (
                stem, _int_str(row.get("ceded_hours", 0)), _int_str(row.get("alae", 0)),
                _diff_str(row.get("ultimate", 0), row.get("paid_to_date", 0))))
            outcome.append("%s|%s|%s" % (stem, row.get("outcome",""), row.get("reason","")))
        for cycle in _CYCLES:
            cap_map = d.get("capacity_per_cycle", {})
            ceil_map = d.get("ceiling_per_cycle", {})
            rem_map = d.get("remainder_dollars_per_cycle", {})
            cells.append("%s|%s|%s|%s|%s" % (
                lob, cycle,
                _int_str(cap_map.get(cycle, 0) if isinstance(cap_map, dict) else None),
                _int_str(ceil_map.get(cycle, 0) if isinstance(ceil_map, dict) else None),
                _int_str(rem_map.get(cycle, 0) if isinstance(rem_map, dict) else None)))
    return {"ledger_backbone": backbone, "ledger_spine": spine,
            "ledger_outcome": outcome, "cells": cells}


def _summary_values(out: Path):
    # The summary.json and treaty_working.json fields no ledger digest
    # carries: run identity, dollar totals, per-LOB figures and the two
    # ceded breakdowns.
    try:
        summary = json.loads((out / "summary.json").read_text())
        treaty = json.loads((out / "treaty_working.json").read_text())
        run = summary.get("run", {})
        totals = summary.get("totals", {})
        lobs = summary.get("lobs", {})
        lines = ["run|lobs|%s" % ",".join(str(v) for v in run.get("lobs", []))]
        for key in ("cycles_total", "admission_instant", "attachment_authority"):
            lines.append("run|%s|%s" % (key, run.get(key)))
        for key in ("total_paid_to_date", "total_incurred", "total_ultimate",
                    "total_alae", "total_ceded", "total_ibnr"):
            lines.append("totals|%s|%s" % (key, _int_str(totals.get(key))))
        for lob in _LOBS:
            entry = lobs.get(lob, {})
            for key in ("claims", "total_paid_to_date", "total_ultimate",
                        "total_ceded", "total_alae"):
                lines.append("lobs|%s|%s|%s" % (lob, key, _int_str(entry.get(key))))
        for group in ("ceded_by_lob", "ceded_by_reinsurer_canonical"):
            parts = treaty.get(group, {})
            for key in sorted(parts):
                lines.append("%s|%s|%s" % (group, key, _int_str(parts[key])))
        return lines
    except Exception:
        return ["unreadable"]


def _digests(out: Path):
    found = {name: _digest(lines) for name, lines in _views(out).items()}
    found["summary_values"] = _digest(_summary_values(out))
    return found


def _module(workspace: Path) -> Path:
    return Path(workspace) / "out" / "reserving.py"


def _delivered(workspace: Path) -> Path:
    return Path(workspace) / "out"


def _source(workspace: Path) -> str:
    return _module(workspace).read_text(errors="replace")


def _unpack(corpus: str, target: Path) -> None:
    data = _EXTRACTS.get(corpus, "")
    if not data or data.startswith("__"):
        raise RuntimeError("extract %s not sealed" % corpus)
    raw = zlib.decompress(base64.b64decode(data))
    with tarfile.open(fileobj=io.BytesIO(raw), mode="r") as archive:
        archive.extractall(target)


def _shuffle_rows(directory: Path) -> None:
    for path in sorted(directory.iterdir()):
        if path.suffix not in {".csv", ".tsv", ".jsonl"}:
            continue
        lines = path.read_text().splitlines()
        if path.suffix in {".csv", ".tsv"}:
            if len(lines) < 4:
                continue
            header, body = lines[0], lines[1:]
        else:
            header, body = None, lines
            if len(body) < 4:
                continue
        middle = len(body) // 2
        rotated = body[middle:] + body[:middle]
        new = ([header] + rotated) if header is not None else rotated
        path.write_text("\n".join(new) + "\n")


def _stage(module: Path, room: str, data: Path, out: Path) -> Path:
    copy = Path(room) / "reserving.py"
    shutil.copyfile(module, copy)
    os.chmod(copy, 0o644)
    os.chmod(room, 0o755)
    for path in [data, out, *data.rglob("*")]:
        os.chown(path, _SOLVER_UID, _SOLVER_UID)
        os.chmod(path, 0o755 if path.is_dir() else 0o644)
    return copy


def _kill_solver_processes() -> None:
    for entry in Path("/proc").iterdir():
        if not entry.name.isdigit():
            continue
        try:
            status = (entry / "status").read_text()
        except OSError:
            continue
        for line in status.splitlines():
            if line.startswith("Uid:") and str(_SOLVER_UID) in line.split()[1:2]:
                try:
                    os.kill(int(entry.name), signal.SIGKILL)
                except (ProcessLookupError, PermissionError):
                    pass
                break


def _launch(copy: Path, room: str, data: Path, out: Path) -> int:
    command = ["setpriv", "--reuid=%d" % _SOLVER_UID, "--regid=%d" % _SOLVER_UID,
               "--clear-groups", sys.executable, "-I", str(copy),
               "--data", str(data), "--out", str(out)]
    process = None
    code = -1
    try:
        process = subprocess.Popen(command, cwd=room, env=dict(_ENV),
                                   stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                                   start_new_session=True)
        try:
            process.communicate(timeout=500)
        except subprocess.TimeoutExpired:
            try:
                os.killpg(os.getpgid(process.pid), signal.SIGKILL)
            except (ProcessLookupError, PermissionError):
                pass
            process.communicate()
        code = process.returncode
    except (OSError, subprocess.SubprocessError):
        code = -1
    finally:
        if process is not None:
            try:
                os.killpg(os.getpgid(process.pid), signal.SIGKILL)
            except (ProcessLookupError, PermissionError):
                pass
        _kill_solver_processes()
    return code


def _run(workspace: Path, tag: str):
    with _RUN_LOCK:
        return _run_unlocked(workspace, tag)


def _run_unlocked(workspace: Path, tag: str):
    if tag in _CACHE:
        return _CACHE[tag]
    corpus = tag.split("_")[0]
    result = {"code": -1, "out": None, "data": None, "before": {}, "after": {},
              "artifact_bytes": {}, "artifact_bytes_rerun": {}}
    module = _module(workspace)
    if not module.is_file():
        _CACHE[tag] = result
        return result
    room = tempfile.mkdtemp(prefix="hold_")
    name = "corpus_%s" % tag.lower() if tag.endswith("named") else "data"
    data = Path(room) / name
    data.mkdir(parents=True, exist_ok=True)
    try:
        _unpack(corpus, data)
    except Exception:
        _CACHE[tag] = result
        return result
    if tag.endswith("perm"):
        _shuffle_rows(data)
    if tag.endswith("missing"):
        victim = data / "cession_q3.tsv"
        if victim.is_file():
            victim.unlink()
    out = Path(room) / "out"
    out.mkdir(parents=True, exist_ok=True)
    copy = _stage(module, room, data, out)
    for path in sorted(data.iterdir()):
        if path.is_file():
            result["before"][path.name] = hashlib.sha256(path.read_bytes()).hexdigest()
    result["code"] = _launch(copy, room, data, out)
    for path in sorted(data.iterdir()):
        if path.is_file():
            result["after"][path.name] = hashlib.sha256(path.read_bytes()).hexdigest()
    for name in _ARTIFACTS:
        p = out / name
        if p.is_file():
            result["artifact_bytes"][name] = p.read_bytes()
    result["out"] = out
    result["data"] = data
    _CACHE[tag] = result
    return result


def _rerun_bytes(workspace: Path, tag: str):
    with _RUN_LOCK:
        return _rerun_bytes_unlocked(workspace, tag)


def _rerun_bytes_unlocked(workspace: Path, tag: str):
    first = _run(workspace, tag)
    second_tag = tag + "_byte_rerun"
    if second_tag in _CACHE:
        return first, _CACHE[second_tag]
    room = tempfile.mkdtemp(prefix="hold_rerun_")
    data = Path(room) / "data"
    data.mkdir(parents=True, exist_ok=True)
    try:
        _unpack(tag.split("_")[0], data)
    except Exception:
        _CACHE[second_tag] = {}
        return first, {}
    out = Path(room) / "out"
    out.mkdir(parents=True, exist_ok=True)
    copy = _stage(_module(workspace), room, data, out)
    _launch(copy, room, data, out)
    rerun = {}
    for name in _ARTIFACTS:
        p = out / name
        if p.is_file():
            rerun[name] = p.read_bytes()
    _CACHE[second_tag] = rerun
    return first, rerun


def _complete(out) -> bool:
    return out is not None and all((out / name).is_file() for name in _ARTIFACTS)


def _literals(workspace: Path):
    tree = ast.parse(_source(workspace))
    numbers = set()
    strings = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Constant):
            if isinstance(node.value, int) and not isinstance(node.value, bool):
                numbers.add(node.value)
            elif isinstance(node.value, str):
                strings.append(node.value)
    return numbers, strings


def _compared_or_assigned_strings(workspace: Path):
    tree = ast.parse(_source(workspace))
    found = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Compare):
            targets = [node]
        elif isinstance(node, (ast.Assign, ast.AnnAssign, ast.AugAssign)) and node.value is not None:
            targets = [node.value]
        else:
            continue
        for target in targets:
            for sub_node in ast.walk(target):
                if isinstance(sub_node, ast.Constant) and isinstance(sub_node.value, str):
                    found.append(sub_node.value)
    return found


def _hardcodes_sample_answers(workspace: Path) -> bool:
    if not _module(workspace).is_file():
        return False
    numbers, strings = _literals(workspace)
    shipped = _expected()["shipped"]
    marks = {shipped["scalars"].get(k) for k in
             ("total_ceded", "total_ultimate", "total_paid_to_date",
              "treaty_ceded_total", "treaty_retention",
              "treaty_working_excess", "treaty_cat_excess")}
    marks = {m for m in marks if isinstance(m, int) and m > 1000}
    if marks & numbers:
        return True
    hexes = set(shipped.get("digests", {}).values())
    if any(v in hexes for v in strings):
        return True
    banned_literal_strings = {"2032-07-01T00:00:00Z"}
    return any(v in banned_literal_strings for v in _compared_or_assigned_strings(workspace))


