@criterion(description="treaty_working.ceded_total equals the sums of ceded_by_lob, ceded_by_reinsurer_canonical and layer_breakdown.")
def cross_artifact_identity_triangle_holds(workspace: Path) -> bool:
    def body():
        out = _delivered(workspace)
        treaty = json.loads((out / "treaty_working.json").read_text())
        total = treaty.get("ceded_total")
        if isinstance(total, bool) or not isinstance(total, int):
            return False
        for group in ("ceded_by_lob", "ceded_by_reinsurer_canonical", "layer_breakdown"):
            parts = treaty.get(group, {})
            if not isinstance(parts, dict):
                return False
            if any(isinstance(v, bool) or not isinstance(v, int) for v in parts.values()):
                return False
            if sum(parts.values()) != total:
                return False
        # No key named UNRESOLVED in ceded_by_reinsurer_canonical.
        for k in treaty.get("ceded_by_reinsurer_canonical", {}):
            if "UNRESOLVED" in k or "unresolved" in k:
                return False
        return True
    try:
        return bool(body())
    except Exception:
        return False


@criterion(description="chain_ladder_development per cycle digests exactly across 130 cells (26 cycles x 5 LOBs); EXCLUDED rows contribute zero.")
def chain_ladder_development_exact(workspace: Path) -> bool:
    def body():
        out = _delivered(workspace)
        shipped = _expected()["shipped"]
        _CYCLES_LOCAL = ["H%02d" % i for i in range(1, 27)]
        lines = []
        for lob in _LOBS:
            d = json.loads((out / f"lob_{lob}.json").read_text())
            dev = d.get("chain_ladder_development", {})
            if not isinstance(dev, dict):
                return False
            for c in _CYCLES_LOCAL:
                v = dev.get(c, 0)
                if isinstance(v, bool) or not isinstance(v, int):
                    return False
                lines.append(f"{lob}|{c}|{v}")
        return _digest(lines) == shipped["digests"]["chain_ladder_development"]
    try:
        return bool(body())
    except Exception:
        return False



